alter table public.knowledge add constraint knowledge_class_check check (knowledge_class in ('CANONICAL','DERIVED','LEARNED','IMPORTED','TEMPORARY')); alter table public.knowledge add constraint knowledge_scope_check check (scope in ('PRIVATE','GENERAL')); alter table public.knowledge add constraint knowledge_visibility_check check (visibility in ('OWNER_ONLY','SHARED')); alter table public.knowledge add constraint knowledge_confidence_check check (confidence is null or (confidence >= 0 and confidence <= 1)); alter table public.knowledge add constraint knowledge_version_check check (version >= 1); alter table public.knowledge add constraint knowledge_lifecycle_check check (lifecycle in ('CANDIDATE','ACCEPTED','INDEXED','ACTIVE','UPDATED','DEPRECATED','ARCHIVED')); alter table public.knowledge add constraint knowledge_superseded_by_fkey foreign key (superseded_by) references public.knowledge(knowledge_id);
